import EfiPy2 as EfiPy

_CopyMemPrgm  = None
_CopyMemCode  = None
_CopyMemBytes = None
_CopyMemFunc  = None

def _GetCopyMemFunc ():
  global _CopyMemPrgm, _CopyMemCode, _CopyMemBytes, _CopyMemFunc

  if _CopyMemFunc is not None:
    return _CopyMemFunc

  import corepy.arch.x86_64.isa as x86
  import corepy.arch.x86_64.types.registers as reg
  import corepy.arch.x86_64.lib.memory as mem
  import corepy.arch.x86_64.platform as env

  prgm = env.Program ()
  code = prgm.get_stream ()

  lbl_unit2 = prgm.get_unique_label ('unit2')
  lbl_unit8 = prgm.get_unique_label ('unit8')
  lbl_loop4 = prgm.get_unique_label ('loop4')
  lbl_tail4 = prgm.get_unique_label ('tail4')
  lbl_loop2 = prgm.get_unique_label ('loop2')
  lbl_tail2 = prgm.get_unique_label ('tail2')
  lbl_loop8 = prgm.get_unique_label ('loop8')
  lbl_tail8 = prgm.get_unique_label ('tail8')
  lbl_tail  = prgm.get_unique_label ('tail')
  lbl_loop1 = prgm.get_unique_label ('loop1')
  lbl_done  = prgm.get_unique_label ('done')

  # Parameters saved by CorePy x86_64 prologue:
  # [rbp - 0x20]: SrcAddr (Arg 1, rcx)
  # [rbp - 0x18]: DstAddr (Arg 2, rdx)
  # [rbp - 0x10]: Size    (Arg 3, r8)
  # [rbp - 0x08]: Unit    (Arg 4, r9)
  code.add (x86.mov (reg.rsi, mem.MemRef (reg.rbp, -0x20)))
  code.add (x86.mov (reg.rdi, mem.MemRef (reg.rbp, -0x18)))
  code.add (x86.mov (reg.r8,  mem.MemRef (reg.rbp, -0x10)))
  code.add (x86.mov (reg.r9,  mem.MemRef (reg.rbp, -0x08)))

  code.add (x86.cmp (reg.r9, 1))
  code.add (x86.je (lbl_tail))
  code.add (x86.cmp (reg.r9, 2))
  code.add (x86.je (lbl_unit2))
  code.add (x86.cmp (reg.r9, 8))
  code.add (x86.je (lbl_unit8))

  # Default: Unit == 4 (DWORD scalar access)
  code.add (x86.mov (reg.rcx, reg.r8))
  code.add (x86.shr (reg.rcx, 2))
  code.add (x86.jz (lbl_tail4))
  code.add (lbl_loop4)
  code.add (x86.mov (reg.eax, mem.MemRef (reg.rsi, 0, data_size = 32)))
  code.add (x86.mov (mem.MemRef (reg.rdi, 0, data_size = 32), reg.eax))
  code.add (x86.add (reg.rsi, 4))
  code.add (x86.add (reg.rdi, 4))
  code.add (x86.dec (reg.rcx))
  code.add (x86.jnz (lbl_loop4))
  code.add (lbl_tail4)
  code.add (x86.and_ (reg.r8, 3))
  code.add (x86.jmp (lbl_tail))

  # Unit == 2 (WORD scalar access)
  code.add (lbl_unit2)
  code.add (x86.mov (reg.rcx, reg.r8))
  code.add (x86.shr (reg.rcx, 1))
  code.add (x86.jz (lbl_tail2))
  code.add (lbl_loop2)
  code.add (x86.mov (reg.ax, mem.MemRef (reg.rsi, 0, data_size = 16)))
  code.add (x86.mov (mem.MemRef (reg.rdi, 0, data_size = 16), reg.ax))
  code.add (x86.add (reg.rsi, 2))
  code.add (x86.add (reg.rdi, 2))
  code.add (x86.dec (reg.rcx))
  code.add (x86.jnz (lbl_loop2))
  code.add (lbl_tail2)
  code.add (x86.and_ (reg.r8, 1))
  code.add (x86.jmp (lbl_tail))

  # Unit == 8 (QWORD scalar access)
  code.add (lbl_unit8)
  code.add (x86.mov (reg.rcx, reg.r8))
  code.add (x86.shr (reg.rcx, 3))
  code.add (x86.jz (lbl_tail8))
  code.add (lbl_loop8)
  code.add (x86.mov (reg.rax, mem.MemRef (reg.rsi, 0, data_size = 64)))
  code.add (x86.mov (mem.MemRef (reg.rdi, 0, data_size = 64), reg.rax))
  code.add (x86.add (reg.rsi, 8))
  code.add (x86.add (reg.rdi, 8))
  code.add (x86.dec (reg.rcx))
  code.add (x86.jnz (lbl_loop8))
  code.add (lbl_tail8)
  code.add (x86.and_ (reg.r8, 7))

  # Tail / Unit == 1 (BYTE scalar access)
  code.add (lbl_tail)
  code.add (x86.mov (reg.rcx, reg.r8))
  code.add (x86.test (reg.rcx, reg.rcx))
  code.add (x86.jz (lbl_done))
  code.add (lbl_loop1)
  code.add (x86.mov (reg.al, mem.MemRef (reg.rsi, 0, data_size = 8)))
  code.add (x86.mov (mem.MemRef (reg.rdi, 0, data_size = 8), reg.al))
  code.add (x86.add (reg.rsi, 1))
  code.add (x86.add (reg.rdi, 1))
  code.add (x86.dec (reg.rcx))
  code.add (x86.jnz (lbl_loop1))

  code.add (lbl_done)

  prgm.add (code)
  CodeAddr, CodeBytes = prgm.get_code_bytes ()

  FuncType = EfiPy.CFUNCTYPE (
    None,
    EfiPy.UINT64,
    EfiPy.UINT64,
    EfiPy.UINT64,
    EfiPy.UINT64
  )

  _CopyMemPrgm  = prgm
  _CopyMemCode  = code
  _CopyMemBytes = CodeBytes
  _CopyMemFunc  = FuncType (CodeAddr)

  return _CopyMemFunc

def CopyMemory (DumpData, DumpType, Unit: int = 4):
  """
  Safely copy memory from an MMIO ctypes structure into a system RAM ctypes structure
  using CorePy generated x86_64 scalar load/store machine code.

  :param DumpData: Source ctypes Structure or Union instance (e.g. from MMIO)
  :param DumpType: Destination ctypes Structure or Union class type
  :param Unit:     Access width in bytes per load (default 4):
                   1 = UINT8  (1 Byte, Byte access)
                   2 = UINT16 (2 Bytes, Word access)
                   4 = UINT32 (4 Bytes, DWORD access, standard for PCIe ECAM)
                   8 = UINT64 (8 Bytes, QWORD access, for 64-bit MMIO/DRAM only)
  :return:         A new ctypes Structure/Union instance allocated in system RAM
  """
  Size    = EfiPy.sizeof (DumpType)
  SrcAddr = EfiPy.addressof (DumpData)
  DumpObj = DumpType ()
  DstAddr = EfiPy.addressof (DumpObj)

  CopyFunc = _GetCopyMemFunc ()
  CopyFunc (SrcAddr, DstAddr, Size, Unit)

  return DumpObj

